    int targetSum = 50;

    System.out.println("Problem: Make sum=" + targetSum + " with US coins " + java.util.Arrays.toString(coins));

    CoinChangeResult result = CoinChange.builder()
        .withStrategyType(StrategyType.SPACE_OPTIMIZED)
        .enableMetrics()
        .build()
